using System.Data;
using System.Security.Cryptography;
using Microsoft.Data.SqlClient;
using Kaluz.Web.Models;
namespace Kaluz.Web.Services;
public class KaluzService(Db db){
 public static string Hash(string pwd){byte[] salt=RandomNumberGenerator.GetBytes(16);byte[] bytes=Rfc2898DeriveBytes.Pbkdf2(pwd,salt,210000,HashAlgorithmName.SHA256,32);return "PBKDF2$210000$"+Convert.ToBase64String(salt)+"$"+Convert.ToBase64String(bytes);}
 public static bool Verify(string pwd,string stored){try{var a=stored.Split('$');if(a.Length!=4||a[0]!="PBKDF2")return false;var calc=Rfc2898DeriveBytes.Pbkdf2(pwd,Convert.FromBase64String(a[2]),int.Parse(a[1]),HashAlgorithmName.SHA256,32);return CryptographicOperations.FixedTimeEquals(calc,Convert.FromBase64String(a[3]));}catch{return false;}}
 public int Setup(string name,string email,string pass){using var c=db.Open();using var t=c.BeginTransaction(IsolationLevel.Serializable);using var check=new SqlCommand("SELECT COUNT(*) FROM Usuario WITH (UPDLOCK,HOLDLOCK)",c,t);if((int)check.ExecuteScalar()!>0)throw new InvalidOperationException("Ya existe un usuario; la configuración inicial está deshabilitada.");using var cmd=new SqlCommand("INSERT INTO Usuario(IdRol,NombreCompleto,Email,PasswordHash) SELECT IdRol,@n,@e,@p FROM Rol WHERE Nombre='Administrador'",c,t);cmd.Parameters.AddRange([Db.P("@n",name),Db.P("@e",email),Db.P("@p",Hash(pass))]);int n=cmd.ExecuteNonQuery();t.Commit();return n;}
 public void ChangePassword(int uid,string current,string next){var h=Convert.ToString(db.Scalar("SELECT PasswordHash FROM Usuario WHERE IdUsuario=@id AND Activo=1",Db.P("@id",uid)));if(h==null||!Verify(current,h))throw new InvalidOperationException("Contraseña actual incorrecta.");db.Exec("UPDATE Usuario SET PasswordHash=@h WHERE IdUsuario=@id",Db.P("@h",Hash(next)),Db.P("@id",uid));}
 public void CreateUser(string name,string email,string password,int role){if(password.Length<8)throw new InvalidOperationException("La contraseña debe tener 8 caracteres como mínimo.");db.Exec("INSERT INTO Usuario(IdRol,NombreCompleto,Email,PasswordHash) VALUES(@r,@n,@e,@h)",Db.P("@r",role),Db.P("@n",name),Db.P("@e",email),Db.P("@h",Hash(password)));}
 public int Sale(SaleForm f,int uid){if(f.MetodoPagoId<1||f.Lineas.Count==0||f.Lineas.Count>40||f.Lineas.Any(x=>x.Cantidad<1)||f.Descuento<0)throw new InvalidOperationException("Verifica las cantidades y el descuento.");if(f.Lineas.GroupBy(x=>x.VarianteId).Any(x=>x.Count()>1))throw new InvalidOperationException("No repitas una variante.");using var c=db.Open();using var t=c.BeginTransaction(IsolationLevel.Serializable);try{
 int caja=ValInt(c,t,"SELECT TOP 1 IdCaja FROM Caja WITH (UPDLOCK,HOLDLOCK) WHERE IdUsuario=@u AND Estado='Abierta'",Db.P("@u",uid));if(caja==0)throw new InvalidOperationException("Debes abrir caja antes de registrar ventas.");
 decimal sub=0;var rows=new List<(int id,int qty,decimal price)>();foreach(var l in f.Lineas){using var q=new SqlCommand("SELECT p.PrecioVenta,v.StockActual FROM ProductoVariante v WITH (UPDLOCK,HOLDLOCK) JOIN Producto p ON p.IdProducto=v.IdProducto WHERE v.IdVariante=@v AND v.Activo=1 AND p.Activo=1",c,t);q.Parameters.AddWithValue("@v",l.VarianteId);using var r=q.ExecuteReader();if(!r.Read())throw new InvalidOperationException("Variante no disponible: "+l.VarianteId);decimal price=r.GetDecimal(0);int stock=r.GetInt32(1);r.Close();if(stock<l.Cantidad)throw new InvalidOperationException("Stock insuficiente en variante "+l.VarianteId);rows.Add((l.VarianteId,l.Cantidad,price));sub+=price*l.Cantidad;}
 if(f.Descuento>sub)throw new InvalidOperationException("Descuento superior al subtotal.");
 int saleId=ValInt(c,t,"INSERT INTO Venta(NumeroTicket,IdCliente,IdUsuario,IdCaja,IdMetodoPago,Subtotal,Descuento,Total) OUTPUT INSERTED.IdVenta VALUES('PEND-'+CONVERT(varchar(36),NEWID()),@cl,@u,@c,@m,@s,@d,@tot)",Db.P("@cl",f.ClienteId),Db.P("@u",uid),Db.P("@c",caja),Db.P("@m",f.MetodoPagoId),Db.P("@s",sub),Db.P("@d",f.Descuento),Db.P("@tot",sub-f.Descuento));
 Run(c,t,"UPDATE Venta SET NumeroTicket='KZ-'+RIGHT('00000000'+CONVERT(varchar(20),IdVenta),8) WHERE IdVenta=@id",Db.P("@id",saleId));
 foreach(var x in rows){Run(c,t,"INSERT INTO DetalleVenta(IdVenta,IdVariante,Cantidad,PrecioUnitario,Subtotal) VALUES(@v,@id,@q,@p,@s)",Db.P("@v",saleId),Db.P("@id",x.id),Db.P("@q",x.qty),Db.P("@p",x.price),Db.P("@s",x.price*x.qty));Run(c,t,"UPDATE ProductoVariante SET StockActual=StockActual-@q WHERE IdVariante=@id",Db.P("@q",x.qty),Db.P("@id",x.id));Run(c,t,"INSERT INTO MovimientoInventario(IdVariante,Tipo,Cantidad,StockResultante,Motivo,Referencia,IdUsuario) SELECT IdVariante,'Salida',@q,StockActual,'Venta',@ref,@u FROM ProductoVariante WHERE IdVariante=@id",Db.P("@q",x.qty),Db.P("@ref","V-"+saleId),Db.P("@u",uid),Db.P("@id",x.id));}
 if(sub-f.Descuento>0)Run(c,t,"INSERT INTO MovimientoCaja(IdCaja,Tipo,Concepto,Monto,Referencia,IdMetodoPago) VALUES(@c,'Ingreso','Venta',@m,@r,@metodo)",Db.P("@c",caja),Db.P("@m",sub-f.Descuento),Db.P("@r","V-"+saleId),Db.P("@metodo",f.MetodoPagoId));Audit(c,t,uid,"Crear","Venta",saleId);t.Commit();return saleId;
 }catch{t.Rollback();throw;}}
 public int Purchase(PurchaseForm f,int uid){if(f.Lineas.Count<1||f.Lineas.Count>40||f.Lineas.Any(x=>x.Cantidad<=0||x.Costo<0))throw new InvalidOperationException("Detalle de compra inválido.");using var c=db.Open();using var t=c.BeginTransaction();try{decimal total=f.Lineas.Sum(x=>x.Cantidad*x.Costo);int id=ValInt(c,t,"INSERT INTO Compra(IdProveedor,IdUsuario,NumeroDocumento,Total,Estado) OUTPUT INSERTED.IdCompra VALUES(@p,@u,@d,@t,'Pendiente')",Db.P("@p",f.ProveedorId),Db.P("@u",uid),Db.P("@d",f.Documento),Db.P("@t",total));foreach(var x in f.Lineas)Run(c,t,"INSERT INTO DetalleCompra(IdCompra,IdVariante,Cantidad,CostoUnitario,Subtotal) VALUES(@c,@v,@q,@p,@s)",Db.P("@c",id),Db.P("@v",x.VarianteId),Db.P("@q",x.Cantidad),Db.P("@p",x.Costo),Db.P("@s",x.Cantidad*x.Costo));Audit(c,t,uid,"Crear","Compra",id);t.Commit();return id;}catch{t.Rollback();throw;}}
 public void Receive(int detail,int qty,int uid){if(qty<1)throw new InvalidOperationException("Cantidad inválida.");using var c=db.Open();using var t=c.BeginTransaction(IsolationLevel.Serializable);try{using var cmd=new SqlCommand("SELECT d.IdCompra,d.IdVariante,d.Cantidad,d.CantidadRecibida,c.Estado FROM DetalleCompra d WITH(UPDLOCK,HOLDLOCK) JOIN Compra c ON c.IdCompra=d.IdCompra WHERE d.IdDetalleCompra=@id",c,t);cmd.Parameters.AddWithValue("@id",detail);using var r=cmd.ExecuteReader();if(!r.Read())throw new InvalidOperationException("Detalle no encontrado.");int purchase=r.GetInt32(0),variant=r.GetInt32(1),ordered=r.GetInt32(2),received=r.GetInt32(3);string state=r.GetString(4);r.Close();if(state=="Anulada"||received+qty>ordered)throw new InvalidOperationException("La recepción excede lo comprado o la compra está anulada.");Run(c,t,"UPDATE DetalleCompra SET CantidadRecibida=CantidadRecibida+@q WHERE IdDetalleCompra=@d",Db.P("@q",qty),Db.P("@d",detail));Run(c,t,"UPDATE ProductoVariante SET StockActual=StockActual+@q WHERE IdVariante=@v",Db.P("@q",qty),Db.P("@v",variant));Run(c,t,"INSERT INTO MovimientoInventario(IdVariante,Tipo,Cantidad,StockResultante,Motivo,Referencia,IdUsuario) SELECT IdVariante,'Entrada',@q,StockActual,'Recepción de compra',@r,@u FROM ProductoVariante WHERE IdVariante=@v",Db.P("@q",qty),Db.P("@r","C-"+purchase),Db.P("@u",uid),Db.P("@v",variant));Run(c,t,"UPDATE Compra SET Estado=CASE WHEN NOT EXISTS(SELECT 1 FROM DetalleCompra WHERE IdCompra=@id AND CantidadRecibida<Cantidad) THEN 'Recibida' ELSE 'Parcial' END WHERE IdCompra=@id",Db.P("@id",purchase));Audit(c,t,uid,"Recibir","Compra",purchase);t.Commit();}catch{t.Rollback();throw;}}
 public void Adjust(StockForm f,int uid){if(f.Diferencia==0)throw new InvalidOperationException("Indica una cantidad distinta de cero.");using var c=db.Open();using var t=c.BeginTransaction(IsolationLevel.Serializable);try{if(ValInt(c,t,"SELECT COUNT(*) FROM ProductoVariante WHERE IdVariante=@v",Db.P("@v",f.VarianteId))==0)throw new InvalidOperationException("Variante no encontrada.");int stock=ValInt(c,t,"SELECT StockActual FROM ProductoVariante WITH(UPDLOCK,HOLDLOCK) WHERE IdVariante=@v",Db.P("@v",f.VarianteId));if(stock+f.Diferencia<0)throw new InvalidOperationException("El stock no puede ser negativo.");Run(c,t,"UPDATE ProductoVariante SET StockActual=StockActual+@q WHERE IdVariante=@v",Db.P("@q",f.Diferencia),Db.P("@v",f.VarianteId));Run(c,t,"INSERT INTO MovimientoInventario(IdVariante,Tipo,Cantidad,StockResultante,Motivo,IdUsuario) SELECT IdVariante,'Ajuste',@q,StockActual,@m,@u FROM ProductoVariante WHERE IdVariante=@v",Db.P("@q",f.Diferencia),Db.P("@m",f.Motivo),Db.P("@u",uid),Db.P("@v",f.VarianteId));Audit(c,t,uid,"Ajustar","Stock",f.VarianteId);t.Commit();}catch{t.Rollback();throw;}}
 public void CancelSale(int sale,int uid){using var c=db.Open();using var t=c.BeginTransaction(IsolationLevel.Serializable);try{using var cmd=new SqlCommand("SELECT Estado,IdCaja,Total,IdMetodoPago FROM Venta WITH(UPDLOCK,HOLDLOCK) WHERE IdVenta=@id",c,t);cmd.Parameters.AddWithValue("@id",sale);using var r=cmd.ExecuteReader();if(!r.Read())throw new InvalidOperationException("Venta no encontrada.");string state=r.GetString(0);int caja=r.GetInt32(1);decimal total=r.GetDecimal(2);int metodo=r.GetInt32(3);r.Close();if(state!="Completada")throw new InvalidOperationException("Venta previamente anulada.");if(ValInt(c,t,"SELECT COUNT(*) FROM Devolucion WHERE IdVenta=@v",Db.P("@v",sale))>0)throw new InvalidOperationException("Venta con devoluciones registradas; no puede anularse.");if(ValInt(c,t,"SELECT COUNT(*) FROM Caja WHERE IdCaja=@id AND Estado='Abierta'",Db.P("@id",caja))==0)throw new InvalidOperationException("La caja de esta venta está cerrada.");using var d=new SqlCommand("SELECT IdVariante,Cantidad FROM DetalleVenta WHERE IdVenta=@v ORDER BY IdVariante",c,t);d.Parameters.AddWithValue("@v",sale);var lines=new List<(int,int)>();using(var rd=d.ExecuteReader())while(rd.Read())lines.Add((rd.GetInt32(0),rd.GetInt32(1)));foreach(var x in lines){Run(c,t,"UPDATE ProductoVariante SET StockActual=StockActual+@q WHERE IdVariante=@v",Db.P("@q",x.Item2),Db.P("@v",x.Item1));Run(c,t,"INSERT INTO MovimientoInventario(IdVariante,Tipo,Cantidad,StockResultante,Motivo,Referencia,IdUsuario) SELECT IdVariante,'Entrada',@q,StockActual,'Anulación venta',@r,@u FROM ProductoVariante WHERE IdVariante=@v",Db.P("@q",x.Item2),Db.P("@r","V-"+sale),Db.P("@u",uid),Db.P("@v",x.Item1));}Run(c,t,"UPDATE Venta SET Estado='Anulada',MotivoAnulacion='Anulación por usuario autorizado' WHERE IdVenta=@v",Db.P("@v",sale));if(total>0)Run(c,t,"INSERT INTO MovimientoCaja(IdCaja,Tipo,Concepto,Monto,Referencia,IdMetodoPago) VALUES(@c,'Egreso','Anulación de venta',@m,@r,@metodo)",Db.P("@c",caja),Db.P("@m",total),Db.P("@r","V-"+sale),Db.P("@metodo",metodo));Audit(c,t,uid,"Anular","Venta",sale);t.Commit();}catch{t.Rollback();throw;}}
 public int Return(ReturnForm f,int uid){if(f.Cantidad<1||!(new[]{"Cambio","Devolucion"}).Contains(f.Tipo))throw new InvalidOperationException("Datos inválidos.");if(f.Tipo=="Cambio"&&!f.VarianteCambio.HasValue)throw new InvalidOperationException("Selecciona variante de cambio.");using var c=db.Open();using var t=c.BeginTransaction(IsolationLevel.Serializable);try{using var cmd=new SqlCommand("SELECT dv.IdVenta,dv.IdVariante,dv.Cantidad,dv.PrecioUnitario,v.IdCaja,v.Estado,v.IdMetodoPago,v.Subtotal,v.Descuento FROM DetalleVenta dv WITH(UPDLOCK,HOLDLOCK) JOIN Venta v ON v.IdVenta=dv.IdVenta WHERE dv.IdDetalleVenta=@d AND dv.IdVenta=@v",c,t);cmd.Parameters.AddWithValue("@d",f.DetalleVentaId);cmd.Parameters.AddWithValue("@v",f.VentaId);using var r=cmd.ExecuteReader();if(!r.Read())throw new InvalidOperationException("Detalle de venta no encontrado.");int oldVar=r.GetInt32(1),sold=r.GetInt32(2),caja=r.GetInt32(4);decimal price=r.GetDecimal(3);string state=r.GetString(5);int metodo=r.GetInt32(6);decimal subtotalVenta=r.GetDecimal(7),descuentoVenta=r.GetDecimal(8);r.Close();if(state!="Completada")throw new InvalidOperationException("Venta anulada.");int returned=ValInt(c,t,"SELECT COALESCE(SUM(dd.Cantidad),0) FROM DetalleDevolucion dd JOIN Devolucion d ON dd.IdDevolucion=d.IdDevolucion WHERE dd.IdDetalleVenta=@d",Db.P("@d",f.DetalleVentaId));if(returned+f.Cantidad>sold)throw new InvalidOperationException("Cantidad devuelta mayor que la vendida.");if(ValInt(c,t,"SELECT COUNT(*) FROM Caja WHERE IdCaja=@c AND Estado='Abierta'",Db.P("@c",caja))==0)throw new InvalidOperationException("La caja original está cerrada; gestionar devolución manualmente.");decimal precioNeto=subtotalVenta>0 ? price*(subtotalVenta-descuentoVenta)/subtotalVenta : 0;decimal refund=f.Tipo=="Devolucion"?Math.Round(precioNeto*f.Cantidad,2,MidpointRounding.AwayFromZero):0;int id=ValInt(c,t,"INSERT INTO Devolucion(IdVenta,IdUsuario,Tipo,Motivo,MontoReembolso) OUTPUT INSERTED.IdDevolucion VALUES(@v,@u,@t,@m,@r)",Db.P("@v",f.VentaId),Db.P("@u",uid),Db.P("@t",f.Tipo),Db.P("@m",f.Motivo),Db.P("@r",refund));Run(c,t,"INSERT INTO DetalleDevolucion(IdDevolucion,IdDetalleVenta,Cantidad,IdVarianteCambio,CantidadCambio) VALUES(@d,@l,@q,@n,@c)",Db.P("@d",id),Db.P("@l",f.DetalleVentaId),Db.P("@q",f.Cantidad),Db.P("@n",f.VarianteCambio),Db.P("@c",f.Tipo=="Cambio"?f.Cantidad:null));Run(c,t,"UPDATE ProductoVariante SET StockActual=StockActual+@q WHERE IdVariante=@v",Db.P("@q",f.Cantidad),Db.P("@v",oldVar));Run(c,t,"INSERT INTO MovimientoInventario(IdVariante,Tipo,Cantidad,StockResultante,Motivo,Referencia,IdUsuario) SELECT IdVariante,'Devolucion',@q,StockActual,@m,@r,@u FROM ProductoVariante WHERE IdVariante=@v",Db.P("@q",f.Cantidad),Db.P("@m",f.Tipo),Db.P("@r","D-"+id),Db.P("@u",uid),Db.P("@v",oldVar));if(f.Tipo=="Cambio"){int newVar=f.VarianteCambio!.Value;int remaining=ValInt(c,t,"SELECT StockActual FROM ProductoVariante WITH(UPDLOCK,HOLDLOCK) WHERE IdVariante=@v AND Activo=1",Db.P("@v",newVar));if(remaining<f.Cantidad)throw new InvalidOperationException("Stock insuficiente para el cambio.");using var priceCmd=new SqlCommand("SELECT p.PrecioVenta FROM ProductoVariante v JOIN Producto p ON p.IdProducto=v.IdProducto WHERE v.IdVariante=@v",c,t);priceCmd.Parameters.AddWithValue("@v",newVar);decimal newPrice=Convert.ToDecimal(priceCmd.ExecuteScalar());if(newPrice!=price)throw new InvalidOperationException("El cambio requiere una variante del mismo precio; diferencias pendientes de implementación.");Run(c,t,"UPDATE ProductoVariante SET StockActual=StockActual-@q WHERE IdVariante=@v",Db.P("@q",f.Cantidad),Db.P("@v",newVar));Run(c,t,"INSERT INTO MovimientoInventario(IdVariante,Tipo,Cantidad,StockResultante,Motivo,Referencia,IdUsuario) SELECT IdVariante,'Salida',@q,StockActual,'Cambio',@r,@u FROM ProductoVariante WHERE IdVariante=@v",Db.P("@q",f.Cantidad),Db.P("@r","D-"+id),Db.P("@u",uid),Db.P("@v",newVar));}if(refund>0)Run(c,t,"INSERT INTO MovimientoCaja(IdCaja,Tipo,Concepto,Monto,Referencia,IdMetodoPago) VALUES(@c,'Egreso','Devolución',@m,@r,@metodo)",Db.P("@c",caja),Db.P("@m",refund),Db.P("@r","D-"+id),Db.P("@metodo",metodo));Audit(c,t,uid,"Crear","Devolucion",id);t.Commit();return id;}catch{t.Rollback();throw;}}
 public void OpenCash(int uid,decimal amount){if(amount<0)throw new InvalidOperationException("Monto inválido.");db.Exec("INSERT INTO Caja(IdUsuario,MontoInicial) VALUES(@u,@m)",Db.P("@u",uid),Db.P("@m",amount));}
 public void CashMovement(int uid,string kind,string reason,decimal amount){if(string.IsNullOrWhiteSpace(reason)||amount<=0||!(new[]{"Ingreso","Egreso"}).Contains(kind))throw new InvalidOperationException("Movimiento inválido.");using var c=db.Open();using var t=c.BeginTransaction();try{int cash=ValInt(c,t,"SELECT TOP 1 IdCaja FROM Caja WITH(UPDLOCK,HOLDLOCK) WHERE IdUsuario=@u AND Estado='Abierta'",Db.P("@u",uid));if(cash==0)throw new InvalidOperationException("Caja no abierta.");Run(c,t,"INSERT INTO MovimientoCaja(IdCaja,Tipo,Concepto,Monto,IdMetodoPago) VALUES(@c,@t,@r,@m,(SELECT IdMetodoPago FROM MetodoPago WHERE Nombre='Efectivo'))",Db.P("@c",cash),Db.P("@t",kind),Db.P("@r",reason),Db.P("@m",amount));t.Commit();}catch{t.Rollback();throw;}}
 public void CloseCash(int uid,decimal counted){if(counted<0)throw new InvalidOperationException("Monto inválido.");using var c=db.Open();using var t=c.BeginTransaction(IsolationLevel.Serializable);try{int cash=ValInt(c,t,"SELECT TOP 1 IdCaja FROM Caja WITH(UPDLOCK,HOLDLOCK) WHERE IdUsuario=@u AND Estado='Abierta'",Db.P("@u",uid));if(cash==0)throw new InvalidOperationException("No hay caja abierta.");using var cmd=new SqlCommand("UPDATE Caja SET Estado='Cerrada',FechaCierre=SYSDATETIME(),MontoFinal=@f,MontoEsperado=MontoInicial+COALESCE((SELECT SUM(CASE WHEN Tipo='Ingreso' THEN Monto ELSE -Monto END) FROM MovimientoCaja mc JOIN MetodoPago mp ON mp.IdMetodoPago=mc.IdMetodoPago WHERE mc.IdCaja=@c AND mp.Nombre='Efectivo'),0),Diferencia=@f-(MontoInicial+COALESCE((SELECT SUM(CASE WHEN Tipo='Ingreso' THEN Monto ELSE -Monto END) FROM MovimientoCaja mc JOIN MetodoPago mp ON mp.IdMetodoPago=mc.IdMetodoPago WHERE mc.IdCaja=@c AND mp.Nombre='Efectivo'),0)) WHERE IdCaja=@c",c,t);cmd.Parameters.AddRange([Db.P("@f",counted),Db.P("@c",cash)]);cmd.ExecuteNonQuery();Audit(c,t,uid,"Cerrar","Caja",cash);t.Commit();}catch{t.Rollback();throw;}}
 static int ValInt(SqlConnection c,SqlTransaction t,string sql,params SqlParameter[] ps){using var cmd=new SqlCommand(sql,c,t);cmd.Parameters.AddRange(ps);var x=cmd.ExecuteScalar();return x==null||x==DBNull.Value?0:Convert.ToInt32(x);}
 static void Run(SqlConnection c,SqlTransaction t,string sql,params SqlParameter[] ps){using var cmd=new SqlCommand(sql,c,t);cmd.Parameters.AddRange(ps);cmd.ExecuteNonQuery();}
 static void Audit(SqlConnection c,SqlTransaction t,int uid,string action,string entity,int id){Run(c,t,"INSERT INTO Auditoria(IdUsuario,Accion,Entidad,IdRegistro) VALUES(@u,@a,@e,@i)",Db.P("@u",uid),Db.P("@a",action),Db.P("@e",entity),Db.P("@i",id));}
}
